index 79f2247dd..5b15f9761 100644
--- a/src/com/google/javascript/jscomp/MakeDeclaredNamesUnique.java
+++ b/src/com/google/javascript/jscomp/MakeDeclaredNamesUnique.java
@@ -263,6 +263,81 @@ class MakeDeclaredNamesUnique
     private boolean containsSeparator(String name) {
       return name.indexOf(ContextualRenamer.UNIQUE_ID_SEPARATOR) != -1;
     }
+
+    private boolean checkIfChildScopesWillUseBaseName(Scope parentScope, String baseName) {
+      // Look at the AST to find child functions and check their variable names
+      Node scopeRoot = parentScope.getRootNode();
+      return checkNodeForChildVarsThatWillUseBaseName(scopeRoot, baseName);
+    }
+
+    private boolean checkNodeForChildVarsThatWillUseBaseName(Node node, String baseName) {
+      if (node.getType() == Token.FUNCTION) {
+        // Skip the function name and parameters, look at body
+        Node body = node.getLastChild();
+        return checkNodeForVarsRecursively(body, baseName, true);
+      } else {
+        // For non-function scopes, check all children
+        return checkNodeForVarsRecursively(node, baseName, false);
+      }
+    }
+
+    private boolean checkNodeForVarsRecursively(Node node, String baseName, boolean skipFunctions) {
+      if (node == null) {
+        return false;
+      }
+
+      for (Node child = node.getFirstChild(); child != null; child = child.getNext()) {
+        if (skipFunctions && child.getType() == Token.FUNCTION) {
+          // Look inside function bodies for nested variables
+          // Only check immediate children functions (direct scope children)
+          Node funcBody = child.getLastChild();
+          // Look for VAR declarations in this function body
+          for (Node bodyChild = funcBody.getFirstChild(); bodyChild != null; bodyChild = bodyChild.getNext()) {
+            if (bodyChild.getType() == Token.VAR) {
+              Node varName = bodyChild.getFirstChild();
+              String name = varName.getString();
+              if (containsSeparator(name)) {
+                int index = indexOfSeparator(name);
+                String suffix = getNameSuffix(name, index);
+                if (suffix.matches("\\d+")) {
+                  String revertedName = getOrginalNameInternal(name, index);
+                  if (revertedName.equals(baseName)) {
+                    System.err.println("DEBUG: found child func var " + name + " that reverts to " + baseName);
+                    return true;
+                  }
+                }
+              }
+            }
+          }
+        } else if (child.getType() == Token.VAR) {
+          Node varName = child.getFirstChild();
+          String name = varName.getString();
+          if (containsSeparator(name)) {
+            int index = indexOfSeparator(name);
+            String suffix = getNameSuffix(name, index);
+            if (suffix.matches("\\d+")) {
+              String revertedName = getOrginalNameInternal(name, index);
+              if (revertedName.equals(baseName)) {
+                System.err.println("DEBUG: found child var " + name + " that reverts to " + baseName);
+                return true;
+              }
+            }
+          }
+        }
+      }
+      return false;
+    }
+
+    private boolean isInChildScope(Scope potentialChild, Scope potentialParent) {
+      Scope current = potentialChild.getParent();
+      while (current != null) {
+        if (current == potentialParent) {
+          return true;
+        }
+        current = current.getParent();
+      }
+      return false;
+    }
     private static String getOrginalNameInternal(String name, int index) {
       return name.substring(0, index);
     }
